#include <stdio.h>
/* ex05：4B/5B 编码——用 20% 的冗余换来「足够的跳变」
 * 100BASE-TX / FDDI 的做法：把 4 位一组映射成 5 位。
 * 真实规则不是「跳变数 ≥2」，而是「任意 5 位码字里连续 0 不超过 3 个」：
 * 因为线路用 NRZI（遇 1 翻转、遇 0 保持），只要不出现 4 个以上连续 0，
 * 接收方就一定能从中恢复时钟。
 * 16 个数据码字之外，另外 16 个 5 位码字留给控制符（IDLE、SOF 等）。
 * 编码效率 = 4/5 = 80%（即 100Mbps 线路实际传 125 MBaud）。*/
typedef struct { int nibble; const char *code; } Entry;

int main(void) {
    /* 标准 4B/5B 码表（数据类型部分） */
    Entry tab[16] = {
        {0x0, "11110"}, {0x1, "01001"}, {0x2, "10100"}, {0x3, "10101"},
        {0x4, "01010"}, {0x5, "01011"}, {0x6, "01110"}, {0x7, "01111"},
        {0x8, "10010"}, {0x9, "10011"}, {0xA, "10110"}, {0xB, "10111"},
        {0xC, "11010"}, {0xD, "11011"}, {0xE, "11100"}, {0xF, "11101"}
    };
    unsigned char data[] = {0xA5, 0x3C};        /* 待编码两个字节 */

    printf("4B/5B 编码表（16 个数据码字）\n");
    printf("------------------------------------------------------\n");
    printf("%-8s %-10s %-14s %s\n", "4bit", "5bit 码字", "最长连续0", "说明");
    for (int i = 0; i < 16; i++) {
        /* 统计最长连续 0 的个数（NRZI 下这才是自同步的判据） */
        int run = 0, worst = 0;
        for (int k = 0; k < 5; k++) {
            if (tab[i].code[k] == '0') { run++; if (run > worst) worst = run; }
            else run = 0;
        }
        printf("%-8X %-10s %-14d %s\n", tab[i].nibble, tab[i].code, worst,
               worst <= 3 ? "≤3，接收方可恢复时钟" : "4 个以上连续 0，会失步");
    }
    printf("------------------------------------------------------\n");

    for (int b = 0; b < 2; b++) {
        int hi = (data[b] >> 4) & 0xF, lo = data[b] & 0xF;
        printf("字节 0x%02X -> 高 4 位 %X=%s + 低 4 位 %X=%s  =>  %s%s\n",
               data[b], hi, tab[hi].code, lo, tab[lo].code, tab[hi].code, tab[lo].code);
    }
    printf("\n效率：4/5 = 80%%。100Mbps 的 100BASE-TX 线上实际跑 125 MBaud，\n");
    printf("      多出的 25%% 全花在「保证跳变」上了 —— 这就是自同步的代价。\n");
    return 0;
}
